/**
 * src/lib/commerce/types.ts
 *
 * Provider-neutral types shared by every commerce adapter. Nothing in this
 * file may reference a concrete provider's naming (no "shopify" / "gid://"
 * anywhere in a type name or field name) — the only external import allowed
 * is the `CommerceProvider` / `CommerceConnectionStatus` enums generated by
 * Prisma, which are themselves provider-neutral (Commerce7 is a value of
 * `CommerceProvider`, not a separate type).
 */

import type { CommerceConnectionStatus, CommerceProvider } from "@prisma/client";

/**
 * What a given adapter can actually do. Kept deliberately narrow — only the
 * capabilities the product surface exercises today. Do not add speculative
 * capabilities (orders, attribution, commissions, etc.) until a caller
 * actually needs them.
 */
export type CommerceCapabilities = {
  canSyncProducts: boolean;
  canCreateDiscount: boolean;
  canRevokeDiscount: boolean;
  canVerifyWebhooks: boolean;
};

/**
 * The neutral view of a commerce connection handed to business code.
 *
 * `id` is `null` and `isLegacyFallback` is `true` when this summary was
 * derived from legacy `Brand.shopify*` columns rather than an actual
 * `CommerceConnection` row (pre-migration brands). It never contains any
 * credential field — secrets live only in `CommerceConnectionSecret` and
 * are never surfaced through this type.
 */
export type CommerceConnectionSummary = {
  id: string | null;
  brandId: string;
  provider: CommerceProvider;
  status: CommerceConnectionStatus;
  displayName: string;
  externalAccountId: string;
  storefrontUrl: string | null;
  isPrimary: boolean;
  grantedScopes: string[];
  installedAt: Date | null;
  uninstalledAt: Date | null;
  lastProductSyncAt: Date | null;
  isLegacyFallback: boolean;
};

/**
 * Discriminated result union for connection lookups. Discriminated on the
 * literal `ok` field so callers get exhaustive narrowing without needing a
 * separate discriminant property.
 */
export type CommerceConnectionResult =
  | { ok: true; connection: CommerceConnectionSummary }
  | { ok: false; reason: "NOT_FOUND" | "NOT_CONNECTED" };

/**
 * Neutral product shape covering everything the storefront/reward UI reads
 * today. `externalId` replaces provider-specific ids (e.g. Shopify's
 * `shopifyProductGid`) at the neutral boundary.
 */
export type CommerceProduct = {
  externalId: string;
  title: string;
  handle: string | null;
  productUrl: string;
  imageUrl: string | null;
  images: string[];
  priceText: string | null;
  currency: string;
};

/**
 * Result of a product sync. Products are always fetched live and never
 * persisted (there is no Product table) — "sync" means "fetch, normalize,
 * and report a timestamp", not "reconcile against stored rows".
 */
export type ProductSyncResult = {
  connectionId: string;
  provider: CommerceProvider;
  products: CommerceProduct[];
  productCount: number;
  syncedAt: Date;
};

/**
 * Neutral input for creating a provider discount code. Mirrors the fields
 * `createShopifyRewardDiscountCode` accepts today, generalized so a future
 * provider (Commerce7, etc.) could implement the same shape.
 */
export type CreateDiscountInput = {
  code: string;
  title: string;
  issuedAt: Date;
  validDays: number;
  discountType: "FIXED_AMOUNT" | "PERCENTAGE";
  discountAmountCents: number | null;
  discountPercentageBasisPoints: number | null;
  appliesTo: "ALL_PRODUCTS" | "SPECIFIC_PRODUCTS";
  externalProductIds?: string[];
  minimumSubtotalCents?: number | null;
};

/**
 * Neutral discount result. Field selection matches exactly what
 * `src/app/api/rewards/shopify/redeem/route.ts` persists today
 * (`shopifyDiscountNodeId`, `code`, `expiresAt` on `ShopifyRewardRedemption`)
 * — no additional fields are included since nothing currently consumes
 * them.
 */
export type ProviderDiscount = {
  externalDiscountId: string;
  code: string;
  expiresAt: Date | null;
};

/** Framework-neutral webhook request input — deliberately not `NextRequest`. */
export type WebhookRequestInput = {
  rawBody: string;
  headers: Record<string, string>;
};

/**
 * Neutral event kinds corresponding to the webhook topics handled today
 * (see `src/lib/shopify-webhooks.ts` and its GDPR/mandatory topics:
 * app/uninstalled, shop/redact, customers/data_request, customers/redact).
 */
export type CommerceWebhookEventType =
  | "APP_UNINSTALLED"
  | "ACCOUNT_REDACT"
  | "CUSTOMER_DATA_REQUEST"
  | "CUSTOMER_REDACT";

/** A verified, provider-neutral webhook event. `payload` is intentionally `unknown`, never `any`. */
export type NormalizedWebhookEvent = {
  provider: CommerceProvider;
  type: CommerceWebhookEventType;
  externalAccountId: string;
  receivedAt: Date;
  payload: unknown;
};
